#include <cstdio>
#include <cstdlib>
#include "engine/graphics/source_text.hpp"
namespace {using namespace gf;unsigned checks=0;void check(bool ok,const char* why){++checks;if(!ok){std::fprintf(stderr,"measured source text: %s\n",why);std::abort();}}
ByteView bytes(const std::vector<u8>& b){return {b.data(),b.size()};}
struct Capture final:IRenderBackend {std::vector<Vertex> vertices;std::vector<DrawCall> calls;bool initialize(const RenderConfig&,IWindowBackend*,std::string*)override{return true;}void shutdown()override{}bool upload_vertices(const Vertex* p,std::size_t n)override{vertices.assign(p,p+n);return true;}bool upload_texture(u32,const TextureDesc&)override{return true;}bool upload_matrix(u32,const f32*)override{return true;}void begin_frame(const FrameDesc&)override{vertices.clear();calls.clear();}void submit(const DrawCall& c)override{calls.push_back(c);}void end_frame()override{}void present()override{}};
struct Fixture {SourceFont font;SourceTextMetrics metrics;std::vector<u8> tpl,profile,layout;std::string error;
    bool load(){tpl.resize(120);store_be32(tpl.data(),0x20af30);store_be32(tpl.data()+4,1);store_be32(tpl.data()+8,12);store_be32(tpl.data()+12,20);store_be16(tpl.data()+20,8);store_be16(tpl.data()+22,16);store_be32(tpl.data()+28,56);for(unsigned glyph=0;glyph<2;++glyph)for(unsigned y=1;y<7;++y)for(unsigned x=1;x<(glyph?2u:4u);++x){const auto at=56+glyph*32+y*4+x/2;tpl[at]|=u8(15u<<(x%2?0:4));}u32 hash=2166136261u;for(auto b:tpl)hash=(hash^b)*16777619u;
        profile.resize(28);store_be32(profile.data(),0x4746464e);store_be32(profile.data()+4,1);store_be32(profile.data()+8,hash);for(auto [at,v]:std::array<std::pair<unsigned,u16>,8>{{{12,2},{14,8},{16,2},{18,1},{20,0x8140},{22,0},{24,0x8260},{26,0x8268}}})store_be16(profile.data()+at,v);if(!font.load(bytes(profile),bytes(tpl),&error))return false;
        layout.resize(60);store_be32(layout.data(),0x4746544d);store_be32(layout.data()+4,1);store_be32(layout.data()+8,source_text_metrics_key(font));store_be16(layout.data()+12,2);store_be16(layout.data()+14,8);store_be16(layout.data()+16,2);for(unsigned i=0;i<2;++i){const auto at=20+i*20;store_be16(layout.data()+at,i?0x8268:0x8260);store_be16(layout.data()+at+2,i?3:5);for(unsigned k=0;k<2;++k){store_be16(layout.data()+at+4+k*8,1);store_be16(layout.data()+at+6+k*8,1);store_be16(layout.data()+at+8+k*8,i?2:4);store_be16(layout.data()+at+10+k*8,7);}}return metrics.load(bytes(layout),font,&error);
    }
};}
int main(){using namespace gf;Fixture f;check(f.load(),"owned glyph coverage and bound metrics");std::string encoded;check(f.font.encode_ascii("AI A",&encoded),"encoding");SourceTextMeasure measure;check(f.metrics.measure(encoded,8,&measure)&&measure.ink&&measure.left==1&&measure.top==1&&measure.right==14&&measure.bottom==7&&measure.advance==15,"measured ink/advance with narrow glyph and blank");check(f.metrics.measure(std::string("\x81\x40",2),8,&measure)&&!measure.ink&&measure.advance==2,"blank advances without fake geometry");
    for(auto bad:{std::string("\x82",1),std::string("\x82\x61",2),std::string(1026,'x')})check(!f.metrics.measure(bad,8,&measure)&&!measure.ink,"bad code/extent refuses and clears measurement");
    for(f32 size:{0.f,-1.f,NAN,INFINITY,10001.f})check(!f.metrics.measure(encoded,size,&measure),"invalid size refuses");
    for(unsigned bad=0;bad<8;++bad){auto raw=f.layout;switch(bad){case 0:raw[11]^=1;break;case 1:store_be16(raw.data()+12,1);break;case 2:store_be16(raw.data()+14,7);break;case 3:store_be16(raw.data()+16,0);break;case 4:store_be16(raw.data()+22,3);break;case 5:store_be16(raw.data()+26,0);break;case 6:store_be16(raw.data()+40,0x8260);break;case 7:store_be16(raw.data()+32,2);break;}SourceTextMetrics invalid;check(!invalid.load(bytes(raw),f.font,&f.error)&&!invalid.ready(),"malformed binding/glyph/ink/alpha/advance is rejected");}
    Capture backend;RenderEngine render(backend);SourceTextRenderer text;check(text.load_measured(f.font,f.metrics,render,23),"same shared text renderer measured entry");render.begin_frame({});render.reset_arena();check(text.draw_screen_measured(render,encoded,10,20,8,1,1,0,0xffffffffu)&&render.end_frame()&&backend.calls.size()==1&&backend.vertices.size()==18,"measured string stays one ordinary shared draw");check(backend.vertices[0].x==10&&backend.vertices[6].x==15&&backend.vertices[12].x==20,"glyph pen follows variable advance, not quad overlap");
    render.begin_frame({});render.reset_arena();check(text.draw_screen(render,encoded,10,20,8,4,1,1,0,0xffffffffu)&&render.end_frame()&&backend.vertices[6].x==14&&backend.vertices[12].x==22,"old entry retains caller-supplied fixed advance even after measured load");
    render.begin_frame({});render.reset_arena();check(!text.draw_screen_measured(render,std::string("\x82\x60\x82\x61",4),0,0,8,1,1,0,0xffffffffu)&&render.pending_draws()==0,"late unknown glyph publishes no partial string");check(!text.draw_screen(render,"",0,0,8,NAN,1,1,0,0xffffffffu),"old empty-string invalid-advance guard is retained");check(render.end_frame(),"refusal frame closes");
    check(text.load(f.font,render,24)&&!text.draw_screen_measured(render,encoded,0,0,8,1,1,0,0xffffffffu),"ordinary reload clears measured capability");SourceTextMetrics invalid;check(!text.load_measured(f.font,invalid,render,25)&&!text.draw_screen(render,encoded,0,0,8,4,1,1,0,0xffffffffu),"failed measured load cannot reuse old text owner");
    u32 rng=1;for(unsigned test=0;test<128;++test){std::string ascii;f32 pen=0,left=1e6f,right=0;for(unsigned i=0;i<12+test%20;++i){rng=rng*1664525u+1013904223u;const char c="AI "[(rng>>16)%3];ascii+=c;if(c==' '){pen+=2;continue;}left=std::min(left,pen+1);right=std::max(right,pen+(c=='A'?4.f:2.f));pen+=c=='A'?5:3;}check(f.font.encode_ascii(ascii,&encoded)&&f.metrics.measure(encoded,8,&measure)&&measure.left==left&&measure.right==right&&measure.advance==pen,"independent integer-width composition");}
    std::printf("source metrics/layout: %u owned checks PASS (128 numeric text cases, not game cases)\n",checks);return 0;
}
